  I modified openclaw/src/utils/usage-format.ts to check for zero usage before validating the presence of the cost
  configuration. This ensures that if all usage metrics (input, output, cacheRead, cacheWrite) are zero, the function
  returns 0 regardless of whether pricing data is available.

  Additionally, I added a new test case to openclaw/src/utils/usage-format.test.ts to verify this behavior and confirmed
  that all tests pass.

    1 // openclaw/src/utils/usage-format.ts
    2
    3 export function estimateUsageCost(params: {
    4   usage?: NormalizedUsage | UsageTotals | null;
    5   cost?: ModelCostConfig;
    6 }): number | undefined {
    7   const { usage, cost } = params;
    8   if (!usage) {
    9     return undefined;
   10   }
   11
   12   const input = toNumber(usage.input);
   13   const output = toNumber(usage.output);
   14   const cacheRead = toNumber(usage.cacheRead);
   15   const cacheWrite = toNumber(usage.cacheWrite);
   16
   17   if (input === 0 && output === 0 && cacheRead === 0 && cacheWrite === 0) {
   18     return 0;
   19   }
   20
   21   if (!cost) {
   22     return undefined;
   23   }
   24   // ... rest of the logic
